	"html/template"
	"os"
)

func main() {
	tmpl := template.Must(template.New("t").Parse(`<div>{{.}}</div>`))

	// 普通字符串会被转义
	_ = tmpl.Execute(os.Stdout, "<span>hi</span>")
	fmt.Println()

	// 声明成 template.HTML 才原样输出
	_ = tmpl.Execute(os.Stdout, template.HTML("<span>hi</span>"))
	fmt.Println()
}

